@import "tailwindcss";
@import "tw-animate-css";

/*
 * Monochrome Industrial Design System
 * Inspired by Monochrome Industrial's monochrome, typographic, industrial visual language.
 * Source reference: github.com/dominikmartn/monochrome-industrial-design-skill
 *
 * Defaults to dark (OLED black). Add `.light` to <html> for the warm off-white mode.
 */

/* Doto (dot-matrix display face) is loaded on the showcase page. Body/UI
   text uses Geist Mono (already loaded by the web app layout.tsx as
   --font-geist-mono) and Geist Sans for display titles. */
@import url("https://fonts.googleapis.com/css2?family=Doto:wght@400;500;700&display=swap");

@custom-variant dark (&:is(.dark *));

:root {
  /* --- Monochrome Industrial raw palette (dark / OLED) --- */
  --mono-black: #000000;
  --mono-surface: #111111;
  --mono-surface-raised: #1a1a1a;
  --mono-border: #222222;
  --mono-border-visible: #333333;
  --mono-text-disabled: #666666;
  --mono-text-secondary: #999999;
  --mono-text-primary: #e8e8e8;
  --mono-text-display: #ffffff;

  /* --- Monochrome Industrial accent + status (identical across modes) --- */
  --mono-accent: #d71921;          /* signal-light red — one per screen */
  --mono-accent-subtle: rgba(215, 25, 33, 0.15);
  --mono-success: #4a9e5c;
  --mono-warning: #d4a843;
  --mono-error: #d71921;
  --mono-info: #999999;
  --mono-interactive: #5b9bf6;

  /* --- shadcn-shaped tokens mapped to Monochrome Industrial dark mode --- */
  --background: #000000;
  --foreground: #e8e8e8;

  --card: #111111;
  --card-foreground: #e8e8e8;

  --popover: #111111;
  --popover-foreground: #e8e8e8;

  --primary: #ffffff;
  --primary-foreground: #000000;

  --secondary: #1a1a1a;
  --secondary-foreground: #e8e8e8;

  --muted: #111111;
  --muted-foreground: #999999;

  --accent: #d71921;
  --accent-foreground: #ffffff;

  --destructive: #d71921;
  --destructive-foreground: #ffffff;

  --border: #222222;
  --input: #222222;
  --ring: #d71921;
  --radius: 0rem; /* Monochrome Industrial is sharp — pill (999px) or technical (4–8px) only */

  /* --- Type scale --- */
  --display-xl: 4.5rem;
  --display-lg: 3rem;
  --display-md: 2.25rem;
  --heading: 1.5rem;
  --subheading: 1.125rem;
  --body: 1rem;
  --body-sm: 0.875rem;
  --caption: 0.75rem;
  --label: 0.6875rem;

  /* --- Spacing scale (8px base) --- */
  --space-2xs: 0.125rem;
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* --- Motion --- */
  --ease-mono: cubic-bezier(0.25, 0.1, 0.25, 1);
  --duration-micro: 200ms;
  --duration-transition: 350ms;

  /* --- Font families --- */
  --font-display: "Doto", "Space Mono", monospace;
  --font-sans: "Space Grotesk", "DM Sans", system-ui, sans-serif;
  --font-mono: "Space Mono", "JetBrains Mono", "SF Mono", monospace;
}

/* --- Light mode: printed technical manual --- */
.light {
  --mono-black: #f5f5f5;
  --mono-surface: #ffffff;
  --mono-surface-raised: #f0f0f0;
  --mono-border: #e8e8e8;
  --mono-border-visible: #cccccc;
  --mono-text-disabled: #999999;
  --mono-text-secondary: #666666;
  --mono-text-primary: #1a1a1a;
  --mono-text-display: #000000;
  --mono-interactive: #007aff;

  --background: #f5f5f5;
  --foreground: #1a1a1a;

  --card: #ffffff;
  --card-foreground: #1a1a1a;

  --popover: #ffffff;
  --popover-foreground: #1a1a1a;

  --primary: #000000;
  --primary-foreground: #ffffff;

  --secondary: #f0f0f0;
  --secondary-foreground: #1a1a1a;

  --muted: #ffffff;
  --muted-foreground: #666666;

  --accent: #d71921;
  --accent-foreground: #ffffff;

  --destructive: #d71921;
  --destructive-foreground: #ffffff;

  --border: #e8e8e8;
  --input: #e8e8e8;
  --ring: #d71921;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-mono-accent: var(--mono-accent);
  --color-mono-success: var(--mono-success);
  --color-mono-warning: var(--mono-warning);
  --color-mono-text-display: var(--mono-text-display);
  --color-mono-text-primary: var(--mono-text-primary);
  --color-mono-text-secondary: var(--mono-text-secondary);
  --color-mono-text-disabled: var(--mono-text-disabled);
  --color-mono-border: var(--mono-border);
  --color-mono-border-visible: var(--mono-border-visible);
  --color-mono-surface: var(--mono-surface);
  --color-mono-surface-raised: var(--mono-surface-raised);

  --font-display: var(--font-display);
  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  --radius-sm: calc(var(--radius) - 0.25rem);
  --radius-md: calc(var(--radius) - 0.125rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.25rem);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }
  body {
    @apply bg-background text-foreground;
  }
}

@layer components {
  /* --- Dot-matrix motif --- */
  /* Use as a background utility on hero panels, cards, empty states. */
  .dot-grid {
    background-image: radial-gradient(
      circle,
      var(--mono-border-visible) 0.0625rem,
      transparent 0.0625rem
    );
    background-size: 1rem 1rem;
  }

  .dot-grid-subtle {
    background-image: radial-gradient(
      circle,
      var(--mono-border) 0.03125rem,
      transparent 0.03125rem
    );
    background-size: 0.75rem 0.75rem;
  }

  .dot-grid-tight {
    background-image: radial-gradient(
      circle,
      var(--mono-border-visible) 0.0625rem,
      transparent 0.0625rem
    );
    background-size: 0.5rem 0.5rem;
  }

  /* --- Type role helpers --- */
  /* Instrument-panel labels retain their monospace role at small sizes. */
  .mono-label {
    font-family: var(--font-mono);
    font-size: var(--label);
    font-weight: 400;
    letter-spacing: 0;
    text-transform: none;
    color: var(--mono-text-secondary);
  }

  /* Hero numeric / time display — Doto dot-matrix. */
  .mono-display {
    font-family: var(--font-display);
    font-size: var(--display-xl);
    line-height: 1;
    letter-spacing: -0.03em;
    color: var(--mono-text-display);
  }

  /* Monospace data value — for metrics, units, codes. */
  .mono-data {
    font-family: var(--font-mono);
    font-feature-settings: "tnum";
    color: var(--mono-text-primary);
  }
}
